import re


def _strip_tags(text):
    return re.sub(r"@[A-Za-z0-9]+", "", text)


def clean_lines(items, path):
    kept = []
    for raw in items:
        s = _strip_tags(raw).strip(" \t")
        if s and s not in kept:
            kept.append(s)
    with open(path, "w", encoding="utf-8") as fh:
        fh.write("".join(s + "\n" for s in kept))
    return None

